SELECT sys_user.id, sys_user.username, sys_user.email, sys_user.password, sys_user.salt, sys_user.phone, sys_user.avatar, sys_user.organ_id, sys_user.create_time AS ucreate_time, sys_user.update_time AS uupdate_time, sys_user.del_flag AS udel_flag, sys_user.lock_flag AS lock_flag, sys_user.password_change_required, sys_user.organ_id, sys_user.tenant_id, sys_user.type, sys_user.nick_name FROM sys_user sys_user
and sys_user.username = #{username}
and sys_user.email = #{email}
and sys_user.phone = #{phone}

SELECT sys_user.id, sys_user.username, sys_user.email, null password, null salt, sys_user.phone, sys_user.avatar, sys_user.organ_id, sys_user.create_time AS ucreate_time, sys_user.update_time AS uupdate_time, sys_user.del_flag AS udel_flag, sys_user.lock_flag AS lock_flag, sys_user.organ_id, sys_user.tenant_id, sys_user.type, sys_user.nick_name FROM sys_user sys_user
sys_user.del_flag = '0'
and sys_user.id = #{query.id}
and sys_user.type = #{query.type}

SELECT
COUNT(1)
FROM
sys_user sys_user


		and sys_user.username = #{username}


		and sys_user.email = #{email}


		and sys_user.phone = #{phone}
